def get_prime_power_base(k):
    """
    Checks if k is a prime power p^A (A>=2) and returns p, or None if not.
    If k is prime (A=1), it returns None because A must be >= 2.
    If k=1, it returns None.
    """
    if k <= 1:
        return None

    # Iterate through possible prime factors up to sqrt(k)
    for p in range(2, int(k**0.5) + 1):
        if k % p == 0:
            # Check if k is a power of p
            temp = k
            count = 0
            while temp > 1 and temp % p == 0:
                temp //= p
                count += 1

            if temp == 1:
                # k = p^count. Check if count >= 2
                if count >= 2:
                    return p
                # If count is 1, k is prime, which we exclude
                return None 

    # If no factor found up to sqrt(k), k itself is prime.
    # Since we require exponent >= 2, primes are excluded.
    return None

def check_and_record(m, n):
    """
    Checks the condition for (m, n) and returns the prime p if found, otherwise None.
    """
    X = m*m + n
    Y = m + n*n

    # Get prime base for X (p_X)
    p_X = None
    A = 0
    if X > 1:
        temp_X = X
        p_X_candidate = -1

        # Find the unique prime base p_X
        for p in range(2, int(temp_X**0.5) + 1):
            if temp_X % p == 0:
                p_X_candidate = p
                break
        else:
            # X is prime
            p_X_candidate = X

        # Verify p_X_candidate is the base and exponent A >= 2
        if p_X_candidate >= 2:
            temp = X
            A = 0
            while temp > 1 and temp % p_X_candidate == 0:
                temp //= p_X_candidate
                A += 1

            if temp == 1 and A >= 2:
                p_X = p_X_candidate

    # Get prime base for Y (p_Y)
    p_Y = None
    B = 0
    if Y > 1:
        temp_Y = Y
        p_Y_candidate = -1

        # Find the unique prime base p_Y
        for p in range(2, int(temp_Y**0.5) + 1):
            if temp_Y % p == 0:
                p_Y_candidate = p
                break
        else:
            # Y is prime
            p_Y_candidate = Y

        # Verify p_Y_candidate is the base and exponent B >= 2
        if p_Y_candidate >= 2:
            temp = Y
            B = 0
            while temp > 1 and temp % p_Y_candidate == 0:
                temp //= p_Y_candidate
                B += 1

            if temp == 1 and B >= 2:
                p_Y = p_Y_candidate

    # Check if they share the same prime base p and both exponents are >= 2
    if p_X is not None and p_X == p_Y:
        return p_X
    else:
        return None

